fn test_dup_z_i_combo_5_c000_2538e000() {
    // Encoding: 0x2538E000
    // Test DUP_Z.I__ field combination: size=0, sh=1, imm8=0, Zd=0
    // Fields: sh=1, imm8=0, size=0, Zd=0
    let encoding: u32 = 0x2538E000;
    let mut cpu = create_test_cpu();
    write_insn(&mut cpu, 0, encoding);
    let exit = cpu.step().unwrap();
    assert_eq!(
        exit,
        CpuExit::Continue,
        "instruction 0x{:08X} should execute successfully",
        encoding
    );
}

