/// Requirement: FieldExtraction { field: "combination", bit_start: 0, bit_width: 32 }
/// Pg=1 (register index 1 (second register))
#[test]
fn test_fcmuo_p_p_zz_combo_9_c000_6500c400() {
    // Encoding: 0x6500C400
    // Test FCMUO_P.P.ZZ__ field combination: size=0, Zm=0, Pg=1, Zn=0, Pd=0
    // Fields: Zn=0, Zm=0, Pg=1, size=0, Pd=0
    let encoding: u32 = 0x6500C400;
    let mut cpu = create_test_cpu();
    write_insn(&mut cpu, 0, encoding);
    let exit = cpu.step().unwrap();
    assert_eq!(
        exit,
        CpuExit::Continue,
        "instruction 0x{:08X} should execute successfully",
        encoding
    );
}

