/// triggers Undefined
#[test]
fn test_scvtf_z_p_z_w2d_invalid_0_a000_65d0a000() {
    // Encoding: 0x65D0A000
    // Test SCVTF_Z.P.Z_W2D invalid encoding: Unary { op: Not, operand: Call { name: QualifiedIdentifier { qualifier: Any, name: "HaveSVE" }, args: [] } }
    // Fields: Zd=0, Zn=0, Pg=0
    let encoding: u32 = 0x65D0A000;
    let mut cpu = create_test_cpu();
    write_insn(&mut cpu, 0, encoding);
    let exit = cpu.step();
    assert!(
        exit.is_err() || !matches!(exit.unwrap(), CpuExit::Continue),
        "expected UNDEFINED for encoding 0x{:08X}",
        encoding
    );
}

