/// size=1 (16-bit / halfword size)
#[test]
fn test_cmpge_p_p_zw_combo_1_4000_24404000() {
    // Encoding: 0x24404000
    // Test CMPGE_P.P.ZW__ field combination: size=1, Zm=0, Pg=0, Zn=0, Pd=0
    // Fields: Zn=0, size=1, Pd=0, Pg=0, Zm=0
    let encoding: u32 = 0x24404000;
    let mut cpu = create_test_cpu();
    write_insn(&mut cpu, 0, encoding);
    let exit = cpu.step().unwrap();
    assert_eq!(
        exit,
        CpuExit::Continue,
        "instruction 0x{:08X} should execute successfully",
        encoding
    );
}

